def merge(a, b):
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    return out + a[i:] + b[j:]


def merge_k(lists):
    if not lists:
        return []
    while len(lists) > 1:
        nxt = []
        for i in range(0, len(lists), 2):
            if i + 1 < len(lists):
                nxt.append(merge(lists[i], lists[i + 1]))
            else:
                nxt.append(lists[i])
        lists = nxt
    return list(lists[0])

import random


def kth_largest(xs, k):
    a = list(xs)
    target = len(a) - k
    lo, hi = 0, len(a) - 1
    while lo < hi:
        r = random.randint(lo, hi)
        a[r], a[hi] = a[hi], a[r]
        pivot, i = a[hi], lo
        for j in range(lo, hi):
            if a[j] <= pivot:
                a[i], a[j] = a[j], a[i]
                i += 1
        a[i], a[hi] = a[hi], a[i]
        if i == target:
            return a[i]
        if target < i:
            hi = i - 1
        else:
            lo = i + 1
    return a[lo]
